        emon.Testport.assertEq(gtRun(pa, pts, mk, im, Gvec.gvSegments(), out), 4, "four edges");
        emon.Testport.assertEq(gtC(out, 0, 15), Glayer.gqBoxEdge(), "flagged box-edge");
